INSERT INTO database_data_type(database_id,data_type_id,relation_role,relation_note,create_by,update_by) SELECT d.id,t.id,'DIRECT_DATA','CompoDynamics：接口描述明确数据库保存原始测序、核酸/基因组/CDS/DNA条形码或基因序列；不是仅因出现变异、甲基化或项目关联而标注。 来源描述：CompoDynamics is a comprehensive database for characterizing molecular characteristics of coding sequences (CDS). Taking advantage of the exponential growth of RefSeq data, CompoDynamics presents rich molecular properties for each CDS and genome, and provides a portal to compare these properties in different species, family domains and functional genes.','SYSTEM','SYSTEM' FROM database_resource d JOIN data_type t ON t.code='DNA' WHERE d.catalog_id=17 AND NOT EXISTS (SELECT 1 FROM database_data_type r WHERE r.database_id=d.id AND r.data_type_id=t.id);
