INSERT INTO database_data_type(database_id,data_type_id,relation_role,relation_note,create_by,update_by) SELECT d.id,t.id,'DIRECT_DATA','iDOG：接口描述明确数据库保存原始测序、核酸/基因组/CDS/DNA条形码或基因序列；不是仅因出现变异、甲基化或项目关联而标注。 来源描述：the first integrated resource dedicated to domestic dogs and wild canids. It incorporates a variety of omics data, including genome sequences assemblies for dhole and wolf, genomic variations extracted from hundreds of dog/wolf whole genomes, phenotype/disease traits curated from dog research communities and public resources, gene expression profiles derived from published RNA-Seq data, gene ontology for functional annotation, homolog gene information for multiple organisms and disease-related literature.','SYSTEM','SYSTEM' FROM database_resource d JOIN data_type t ON t.code='DNA' WHERE d.catalog_id=40 AND NOT EXISTS (SELECT 1 FROM database_data_type r WHERE r.database_id=d.id AND r.data_type_id=t.id);
INSERT INTO database_data_type(database_id,data_type_id,relation_role,relation_note,create_by,update_by) SELECT d.id,t.id,'DIRECT_DATA','TCOD：接口描述明确数据库保存原始测序、核酸/基因组/CDS/DNA条形码或基因序列；不是仅因出现变异、甲基化或项目关联而标注。 来源描述：TCOD, a multi-omics data platform for tropical crops, provides data service for selective breeding and trait improvement research of tropical crops. Data integrated in TCOD includes Genes, Genomes, Variants, Expressions, Cultivars and Literatures. In addition, TCOD offers online tools for performing genomic data visualization and analyses.','SYSTEM','SYSTEM' FROM database_resource d JOIN data_type t ON t.code='DNA' WHERE d.catalog_id=45 AND NOT EXISTS (SELECT 1 FROM database_data_type r WHERE r.database_id=d.id AND r.data_type_id=t.id);
INSERT INTO database_data_type(database_id,data_type_id,relation_role,relation_note,create_by,update_by) SELECT d.id,t.id,'DIRECT_DATA','RCoV19：接口描述明确数据库保存原始测序、核酸/基因组/CDS/DNA条形码或基因序列；不是仅因出现变异、甲基化或项目关联而标注。 来源描述：RCoV19  (Previously known as 2019nCoVR) features comprehensive integration of genomic and proteomic sequences as well as their metadata information from the GISAID, NCBI, NMDC, CNGB and CNCB/NGDC. It also incorporates a wide range of relevant information including scientific literatures, news, and popular articles for science dissemination, and provides visualization functionalities for genome variation analysis results based on all collected 2019-nCoV strains.','SYSTEM','SYSTEM' FROM database_resource d JOIN data_type t ON t.code='DNA' WHERE d.catalog_id=47 AND NOT EXISTS (SELECT 1 FROM database_data_type r WHERE r.database_id=d.id AND r.data_type_id=t.id);
